    84→    const end = new Date(year, q * 3, 0);
    85→    applyRange(toISO(start), toISO(end));
    86→  };
    87→
    88→  const applyYear = () => {
    89→    applyRange(toISO(new Date(year, 0, 1)), toISO(new Date(year, 11, 31)));
    90→  };
    91→
    92→  const handleFromChange = (v: string) => {
    93→    setFrom(v);
    94→    fetchStats(v, to);
    95→  };
    96→
    97→  const handleToChange = (v: string) => {
    98→    setTo(v);
    99→    fetchStats(from, v);
   100→  };
   101→
   102→  const createExportHeader = () => {
   103→    const header = document.createElement('div');
   104→    header.setAttribute('data-export-inject', 'true');
   105→    header.style.cssText = 'display:flex;align-items:center;gap:12px;padding:16px 24px;background:#1e3a5f;border-radius:8px;margin-bottom:16px;';
   106→    const img = document.createElement('img');
   107→    img.src = '/bosarsa.jpeg';
   108→    img.style.cssText = 'height:36px;border-radius:4px;';
   109→    header.appendChild(img);
   110→    const text = document.createElement('div');
   111→    const title = document.createElement('div');
   112→    title.textContent = 'BOS-ARSA Log';
   113→    title.style.cssText = 'font-size:16px;font-weight:bold;color:#ffffff;letter-spacing:0.5px;';
   114→    text.appendChild(title);
