                      <td className="px-2 sm:px-4 py-2 hidden sm:table-cell"></td>
                      <td className="px-2 sm:px-4 py-2 text-right">{row.participants}</td>
                      <td className="px-2 sm:px-4 py-2 text-right">{row.reports}</td>
                      <td></td>
                    </tr>
                  );
                }
                return null;
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

