          {availableYears.map(y => (
            <button
              key={y}
              onClick={() => setSelectedYear(y)}
              className={`px-3 py-1.5 rounded text-sm font-medium transition-colors ${
                y === selectedYear
                  ? 'bg-[#1e3a5f] text-white'
                  : 'bg-gray-100 hover:bg-blue-100 text-gray-700 hover:text-[#1e3a5f]'
              }`}
            >
              {y}
            </button>
          ))}
        </div>
      )}

